window.isMobile=!1;if(/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)){window.isMobile=!0}
function t_throttle(fn,threshhold,scope){var last;var deferTimer;threshhold||(threshhold=250);return function(){var context=scope||this;var now=+new Date();var args=arguments;if(last&&now<last+threshhold){clearTimeout(deferTimer);deferTimer=setTimeout(function(){last=now;fn.apply(context,args)},threshhold)}else{last=now;fn.apply(context,args)}}}
window.t906showvideo=function(recid){if(document.readyState!=='loading'){t906_showVideo(recid)}else{document.addEventListener('DOMContentLoaded',function(){t906_showVideo(recid)})}
function t906_showVideo(recid){var rec=document.getElementById('rec'+recid);if(!rec)return;var videoContainer=rec.querySelector('.t906__video-container');var videoCover=rec.querySelector('.t906__cover');var youTubeCarrier=rec.querySelector('.t906__video-carier');var vimeoCarrier=rec.querySelector('.t906__video-vimeo');var htmlVideoCarrier=rec.querySelector('.t906__video-html5');if(youTubeCarrier){t906toggleClasses(videoContainer,videoCover);var youTubeID=videoContainer?videoContainer.getAttribute('data-content-popup-video-url-youtube'):'';if(!youTubeID)return;var videoURL=youTubeID?'https://www.youtube.com/embed/'+youTubeID:'';youTubeCarrier.innerHTML='<iframe id="youtubeiframe'+recid+'" class="t906__iframe" width="100%" height="540" src="'+videoURL+'?rel=0&autoplay=1" frameborder="0" allowfullscreen></iframe>'+'<button type="button" class="t906__close"></button>'}
if(vimeoCarrier){var vimeoID=videoContainer?videoContainer.getAttribute('data-content-popup-video-url-vimeo'):'';if(!vimeoID)return;var vimeoPrivacyHash=videoContainer?videoContainer.getAttribute('data-content-popup-video-hash-vimeo'):'';var vimeoURL='';if(vimeoPrivacyHash){vimeoURL=vimeoID?'https://player.vimeo.com/video/'+vimeoID+'?'+vimeoPrivacyHash+'&autoplay=1':''}else{vimeoURL=vimeoID?'https://player.vimeo.com/video/'+vimeoID+'?autoplay=1':''}
t906toggleClasses(videoContainer,videoCover);vimeoCarrier.innerHTML='<iframe id="vimeoiframe'+recid+'" class="t906__iframe" width="100%" height="540" src="'+vimeoURL+'" frameborder="0" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe>'+'<button type="button" class="t906__close"></button>'}
if(htmlVideoCarrier){var html5URL=videoContainer.getAttribute('data-content-popup-video-url-html5');if(!html5URL)return;t906toggleClasses(videoContainer,videoCover);htmlVideoCarrier.innerHTML='<video class="t906__iframe" id="html5video'+recid+'" width="100%" height="540" autoplay controls>'+'<source src="'+html5URL+'" type="video/mp4">'+'Your browser does not support the video tag'+'</video>'+'<button type="button" class="t906__close"></button>'}
var closeButton=rec.querySelector('.t906__close');if(closeButton){closeButton.addEventListener('click',function(){t906hidevideo(recid)})}
var videoBg=rec.querySelector('.t906__video-bg');if(videoBg){videoBg.addEventListener('click',function(){t906hidevideo(recid)})}}
function t906toggleClasses(videoContainer,videoCover){document.body.classList.add('t906__overflow');if(videoCover)videoCover.classList.add('t906__hidden');if(videoContainer)videoContainer.classList.remove('t906__hidden')}};window.t906hidevideo=function(recid){if(document.readyState!=='loading'){t906_hideVideo(recid)}else{document.addEventListener('DOMContentLoaded',function(){t906_hideVideo(recid)})}
function t906_hideVideo(recid){var rec=document.getElementById('rec'+recid);if(!rec)return;var videoContainer=rec.querySelector('.t906__video-container');var videoCover=rec.querySelector('.t906__cover');var videoCarrier=rec.querySelector('.t906__video-carier')||rec.querySelector('.t906__video-vimeo')||rec.querySelector('.t906__video-html5');document.body.classList.remove('t906__overflow');if(videoCover)videoCover.classList.remove('t906__hidden');if(videoContainer)videoContainer.classList.add('t906__hidden');if(videoCarrier)videoCarrier.innerHTML='<div class="t906__video-bg2"></div>'}};function t847_init(recId){t_onFuncLoad('t_card__addFocusOnTab',function(){t_card__addFocusOnTab(recId)})}
function t967_setLogoPadding(recid){var rec=document.getElementById('rec'+recid);if(!rec||window.innerWidth<=980)return;var menu=rec.querySelector('.t967');var logo=menu?menu.querySelector('.t967__logowrapper'):null;var leftWrap=menu?menu.querySelector('.t967__leftwrapper'):null;var rightWrap=menu?menu.querySelector('.t967__rightwrapper'):null;var logoWidth=logo?logo.offsetWidth:0;if(leftWrap)leftWrap.style.paddingRight=logoWidth/2+50+'px';if(rightWrap)rightWrap.style.paddingRight=logoWidth/2+50+'px'}
function t825_initPopup(recId){var rec=document.getElementById('rec'+recId);if(!rec)return;var container=rec.querySelector('.t825');if(!container)return;rec.setAttribute('data-animationappear','off');rec.style.opacity=1;var button=rec.querySelector('.t825__btn');var buttonClose=rec.querySelector('.t825__mobile-close');var popup=rec.querySelector('.t825__popup');var analitics=popup.getAttribute('data-track-popup');var hook='TildaSendMessageWidget'+recId;if(button){button.addEventListener('click',function(event){if(button.classList.contains('t825__btn_active')){t825_closePopup(rec);return}
button.classList.add('t825__btn_active');container.classList.add('t825_active');t825_showPopup(rec);event.preventDefault();if(analitics)Tilda.sendEventToStatistics(analitics,hook)})}
if(buttonClose){buttonClose.addEventListener('click',function(){t825_closePopup(rec)})}
var whatsApp=rec.querySelector('.t825__whatsapp');if(whatsApp){var whatsAppHref=whatsApp.getAttribute('href');if(whatsAppHref)t825_removeExtraSymbolsFromWhatsApp(whatsApp,whatsAppHref)}
t825__lazyLoad()}
function t825_removeExtraSymbolsFromWhatsApp(whatsApp,whatsAppHref){if(whatsAppHref&&whatsAppHref.indexOf('?text=')!==-1){var whatsAppHrefArr=whatsAppHref.split('?text=');whatsAppHrefArr[0]=whatsAppHrefArr[0].replace(/[\(\)+-]/g,'');whatsAppHref=whatsAppHrefArr[0]+'?text='+whatsAppHrefArr[1]}else{whatsAppHref=whatsAppHref.replace(/[\(\)+-]/,'')}
whatsApp.setAttribute('href',whatsAppHref)}
function t825_showPopup(rec){var popup=rec.querySelector('.t825__popup');var buttonWrapper=rec.querySelector('.t825__btn_wrapper');var buttonText=rec.querySelector('.t825__btn-text');if(buttonWrapper)buttonWrapper.classList.remove('t8245_btn_animate');if(buttonText)buttonText.style.display='none';if(window.innerWidth<960)document.body.classList.add('t825__body_popupshowed');popup.style.display='block';setTimeout(function(){popup.classList.add('t825__popup_show')},50);document.addEventListener('keydown',t825__escClosePopup);t825__lazyLoad()}
function t825__escClosePopup(event){if(event.key==='Escape')t825_closePopup()}
function t825_closePopup(rec){if(window.innerWidth<960)document.body.classList.remove('t825__body_popupshowed');var containers=document.querySelectorAll('.t825');var popups=document.querySelectorAll('.t825__popup');var buttons=document.querySelectorAll('.t825__btn');for(var i=0;i<containers.length;i++){containers[i].classList.remove('t825_active')}
for(var i=0;i<popups.length;i++){popups[i].classList.remove('t825__popup_show')}
for(var i=0;i<buttons.length;i++){buttons[i].classList.remove('t825__btn_active')}
setTimeout(function(){if(!rec)return;var popupHide=rec.querySelector('.t825__popup:not(.t825__popup_show)');if(popupHide){popupHide.style.display='none'}},300);document.removeEventListener('keydown',t825__escClosePopup)}
function t825__lazyLoad(){if(window.lazy==='y'||document.getElementById('allrecords').getAttribute('data-tilda-lazy')==='yes'){t_onFuncLoad('t_lazyload_update',function(){t_lazyload_update()})}}